/*
Navbar (Collapse)
*/

$(document).ready(function () {
    
    // If user click outside the box

   // new WOW().init();
    $(document).click(function() {
        $('.dropdown > a.dropdown-toggle').find('i').removeClass('fa-minus-circle').addClass('fa-plus-circle');
        ;
    });

    //$("ul.dropdown-menu").click(function(e) {
    //    e.stopPropagation(); // This is the preferred method.
    //    return false;        // This should not be used unless you do not want
    //});


    //$('.navbar a.dropdown-toggle').on('click', function (e) {
    //    var $el = $(this);
    //    var $parent = $(this).offsetParent(".dropdown-menu");
    //    $(this).parent("li").toggleClass('open');

    //    if (!$parent.parent().hasClass('nav')) {
    //        $el.next().css({ "top": $el[0].offsetTop, "left": $parent.outerWidth() - 4 });
    //    }

    //    $('.nav li.open').not($(this).parents("li")).removeClass("open");

    //    return false;
    //});

    $("#nav li a").on("click", function (e) {
        //allow links to be followed if they don't have a sub-menu
        if (!$(this).parent().has("ul").length) { return; }

        //we have a sub-menu, so stop the link from being followed
        e.preventDefault();

        if (!$(this).hasClass("open")) {
            //we need to know which 'level' we're on 
            var currentLevel = $(this).closest('ul')
            $("li ul", currentLevel).slideUp(350);
            $("li a", currentLevel).removeClass("open");

            // open our new menu and add the open class
            $(this).next("ul").slideDown(350);
            $(this).addClass("open");
        } else {
            $(this).removeClass("open");
            $(this).next("ul").slideUp(350);
        }
    });
});

/*
Plus Minus collapsable
*/

$(function () {
    $('a.dropdown-toggle').click(function () {
        $(this).find('i').toggleClass('fa-minus-circle fa-plus-circle');
    });
});

jQuery('body').bind('click', function (e) {
    if (jQuery(e.target).closest('.navbar').length == 0) {
        // click happened outside of .navbar, so hide
        var opened = jQuery('.navbar-collapse').hasClass('collapse in');
        if (opened === true) {
            jQuery('.navbar-collapse').collapse('hide');
        }
    }
});


