/**
 * PDFAnnotate v1.0.1
 * Author: Ravisha Heshan
 */
var BASE64_MARKER = ';base64,';
var PDFAnnotate = function (container_id, pdfBase64string, options = {}, fabricCanvasOptions = {}) {
	this.number_of_pages = 0;
	this.pages_rendered = 0;
	this.active_tool = 1; // 1 - Free hand, 2 - Text, 3 - Arrow, 4 - Rectangle
	this.fabricObjects = [];
	this.fabricObjectsData = [];
	this.color = '#212121';
	this.borderColor = '#000000';
	this.borderSize = 1;
	this.font_size = 16;
	this.active_canvas = 0;
	this.container_id = container_id;
	this.pdfBase64string = pdfBase64string;
	this.fabricCanvasOptions = fabricCanvasOptions;
	this.pageImageCompression = options.pageImageCompression
		? options.pageImageCompression.toUpperCase()
		: "NONE";
	var inst = this;
	this.addedObjects = 0
	var pdfAsArray = convertDataURIToBinary(this.pdfBase64string);
	var loadingTask = pdfjsLib.getDocument(pdfAsArray);

	loadingTask.promise.then(function (pdf) {
		var scales = { 1: 3.2, 2: 4 },
			defaultScale = 3,
			scale = options && options.scale ? options.scale : (scales[window.devicePixelRatio] || defaultScale);
		this.scale = scale
		//var scale = options.scale ? options.scale : 3;
		inst.number_of_pages = pdf.numPages;
		const maxHeight = 3508;
		const maxWidth = 2480;
		for (var i = 1; i <= pdf.numPages; i++) {
			pdf.getPage(i).then(function (page) {
				const actualPageWidth = page.view[2]
				const actualPageHeight = page.view[3]
				if (actualPageHeight * scale > maxHeight) {
					scale = maxHeight / actualPageHeight
				}
				else if (actualPageWidth * scale > maxWidth) {
					scale = maxWidth / actualPageHeight
				}
				var viewport = page.getViewport({ scale: scale });
				var canvas = document.createElement('canvas');
				document.getElementById(inst.container_id).appendChild(canvas);
				var _page = document.createElement('div');
				_page.innerHTML = `<label class="alert alert-info" style="font-weight: 900;font-size: 17px !important; 
                               margin-top: 10px !important;width: 50%;">  صفحة  ` + (page.pageIndex + 1) + ` من  ` + pdf.numPages + ` </label>`;
				document.getElementById(inst.container_id).appendChild(_page);
				canvas.className = 'pdf-canvas';
				canvas.height = viewport.height;
				canvas.width = viewport.width;
				canvas.style.width = "100%";
				var context = canvas.getContext('2d');
				inst.orientation = (viewport.width > viewport.height) ? 'landscape' : 'portrait';
				var renderContext = {
					canvasContext: context,
					viewport: viewport
				};
				var renderTask = page.render(renderContext);
				renderTask.promise.then(function () {
					$('.pdf-canvas').each(function (index, el) {
						$(el).attr('id', 'page-' + (index + 1) + '-canvas');
					});
					inst.pages_rendered++;
					if (inst.pages_rendered == inst.number_of_pages) inst.initFabric();
				});
			});
		}
	}, function (reason) {
		console.error(reason);
	});
	function convertDataURIToBinary(base64) {
		//dataURI = '' + dataURI
		//var base64Index = dataURI.indexOf(BASE64_MARKER) + BASE64_MARKER.length;
		//var base64 = dataURI.substring(base64Index);
		var raw = window.atob(base64);
		var rawLength = raw.length;
		var array = new Uint8Array(new ArrayBuffer(rawLength));

		for (var i = 0; i < rawLength; i++) {
			array[i] = raw.charCodeAt(i);
		}
		return array;
	}

	this.initFabric = function () {
		var inst = this;
		let canvases = $('#' + inst.container_id + ' canvas')
		canvases.each(function (index, el) {
			var background = el.toDataURL("image/png");
			// Fix touch scroll issue on mobile browsers - start
			(function () {
				var addListener = fabric.util.addListener,
					removeListener = fabric.util.removeListener,
					addEventOptions = { passive: false };

				fabric.util.object.extend(fabric.Canvas.prototype, /** @lends fabric.Canvas.prototype */ {
					_onTouchStart: function (e) {
						var targetR = this.findTarget(e);
						!this.allowTouchScrolling && e.preventDefault && e.preventDefault();
						targetR && e.preventDefault && e.preventDefault();
						if (this.mainTouchId === null) {
							this.mainTouchId = this.getPointerId(e);
						}
						this.__onMouseDown(e);
						this._resetTransformEventData();
						var canvasElement = this.upperCanvasEl,
							eventTypePrefix = this._getEventPrefix();
						addListener(fabric.document, 'touchend', this._onTouchEnd, addEventOptions);
						addListener(fabric.document, 'touchmove', this._onMouseMove, addEventOptions);
						// Unbind mousedown to prevent double triggers from touch devices
						removeListener(canvasElement, eventTypePrefix + 'down', this._onMouseDown);
					}
				});
			})();
			var fabricObj = new fabric.Canvas(el.id, {
				allowTouchScrolling: true,
				selection: false,
				freeDrawingBrush: {
					width: 1,
					color: inst.color
				},
				...inst.fabricCanvasOptions
			});
			fabricObj.selection = false
			inst.fabricObjects.push(fabricObj);
			var disableScroll = function () {
				fabricObj.allowTouchScrolling = false;
			};

			var enableScroll = function () {
				fabricObj.allowTouchScrolling = true;
			};

			fabricObj.on('object:scaling', disableScroll);
			fabricObj.on('object:rotating', disableScroll);
			fabricObj.on('mouse:up', enableScroll);
			fabricObj.on('object:moving', function (e) {
				var obj = e.target;
				disableScroll()
				// if object is too big ignore
				if (obj.currentHeight > obj.canvas.height || obj.currentWidth > obj.canvas.width) {
					return;
				}
				obj.setCoords();
				// top-left  corner
				if (obj.getBoundingRect().top < 0 || obj.getBoundingRect().left < 0) {
					obj.top = Math.max(obj.top, obj.top - obj.getBoundingRect().top);
					obj.left = Math.max(obj.left, obj.left - obj.getBoundingRect().left);
				}
				// bot-right corner
				if (obj.getBoundingRect().top + obj.getBoundingRect().height > obj.canvas.height || obj.getBoundingRect().left + obj.getBoundingRect().width > obj.canvas.width) {
					obj.top = Math.min(obj.top, obj.canvas.height - obj.getBoundingRect().height + obj.top - obj.getBoundingRect().top);
					obj.left = Math.min(obj.left, obj.canvas.width - obj.getBoundingRect().width + obj.left - obj.getBoundingRect().left);
				}
			});
			fabricObj.on('selection:created', this.disableScroll);
			fabricObj.on('selection:cleared', this.enableScroll);
			// Fix touch scroll issue on mobile browsers - End

			if (typeof options.onPageUpdated == 'function') {
				fabricObj.on('object:added', function () {
					var oldValue = Object.assign({}, inst.fabricObjectsData[index]);
					inst.fabricObjectsData[index] = fabricObj.toJSON()
					options.onPageUpdated(index + 1, oldValue, inst.fabricObjectsData[index])
				})
			}
			fabricObj.setBackgroundImage(background, fabricObj.renderAll.bind(fabricObj));
			$(fabricObj.upperCanvasEl).click(function (event) {
				inst.active_canvas = index;
				inst.fabricClickHandler(event, fabricObj);
			});
			$(fabricObj.upperCanvasEl).bind("contextmenu", function (event) {
				// Avoid the real one
				event.preventDefault();
				// Avoid the event from bubbling up to parent
				event.stopPropagation();
				inst.active_canvas = index;
				inst.fabricRightClickHandler(event);
			});
			fabricObj.on('after:render', function () {
				inst.fabricObjectsData[index] = fabricObj.toJSON()
				fabricObj.off('after:render')
			})

			if (index === canvases.length - 1 && typeof options.ready === 'function') {
				options.ready()
			}
		});
	}

	this.fabricClickHandler = function (event, fabricObj) {
		var inst = this;
		console.log(inst.active_canvas);
		//confirm('تم تحديد الصفحة رقم :' + inst.active_canvas);
		if (inst.active_tool == 2) {
			var text = new fabric.IText('Sample text', {
				left: event.clientX - fabricObj.upperCanvasEl.getBoundingClientRect().left,
				top: event.clientY - fabricObj.upperCanvasEl.getBoundingClientRect().top,
				fill: inst.color,
				fontSize: inst.font_size,
				selectable: true
			});
			fabricObj.add(text);
			inst.active_tool = 0;
		}
	}

	this.fabricRightClickHandler = function (event, fabricObj) {
		var inst = this;
		var activeObject = inst.fabricObjects[inst.active_canvas].getActiveObject();
		if (activeObject) {
			if (confirm('Are you sure to delete ?')) {
				inst.fabricObjects[inst.active_canvas].remove(activeObject);
				inst.addedObjects--;
			}
		}
	}
}

PDFAnnotate.prototype.enableSelector = function () {
	var inst = this;
	inst.active_tool = 0;
	if (inst.fabricObjects.length > 0) {
		$.each(inst.fabricObjects, function (index, fabricObj) {
			fabricObj.isDrawingMode = false;
		});
	}
}

PDFAnnotate.prototype.enablePencil = function () {
	var inst = this;
	inst.active_tool = 1;
	if (inst.fabricObjects.length > 0) {
		$.each(inst.fabricObjects, function (index, fabricObj) {
			fabricObj.isDrawingMode = true;
		});
	}
}

PDFAnnotate.prototype.enableAddText = function () {
	var inst = this;
	inst.active_tool = 2;
	if (inst.fabricObjects.length > 0) {
		$.each(inst.fabricObjects, function (index, fabricObj) {
			fabricObj.isDrawingMode = false;
		});
	}
}

PDFAnnotate.prototype.enableRectangle = function () {
	var inst = this;
	var fabricObj = inst.fabricObjects[inst.active_canvas];
	inst.active_tool = 4;
	if (inst.fabricObjects.length > 0) {
		$.each(inst.fabricObjects, function (index, fabricObj) {
			fabricObj.isDrawingMode = false;
		});
	}

	var rect = new fabric.Rect({
		width: 100,
		height: 100,
		fill: inst.color,
		stroke: inst.borderColor,
		strokeSize: inst.borderSize
	});
	fabricObj.add(rect);
}

PDFAnnotate.prototype.enableAddArrow = function () {
	var inst = this;
	inst.active_tool = 3;
	if (inst.fabricObjects.length > 0) {
		$.each(inst.fabricObjects, function (index, fabricObj) {
			fabricObj.isDrawingMode = false;
			new Arrow(fabricObj, inst.color, function () {
				inst.active_tool = 0;
			});
		});
	}
}
PDFAnnotate.prototype.addImageToCanvas = function (imgBase64String, width, pageNo, stamp) {
	try {
		var instance = this;
		var fabricObj = instance.fabricObjects[pageNo > -1 ? pageNo : instance.active_canvas];
		var x = 0, y = 0;
		console.log(fabricObj.width);
		if (fabricObj) {
			var image = new Image();
			image.onload = function () {
				var Img = new fabric.Image(image);
				const offsetX = (image.width / 2),
					offsetY = (image.height / 2);

				x = stamp ? (stamp.left + image.width / 2) : fabricObj._previousPointer.x;
				y = stamp ? (stamp.top + image.height / 2) : fabricObj._previousPointer.y;
				const left = x - offsetX,
					top = y - offsetY;
				let scale = (width / Img.width)
				if (fabricObj.width < fabricObj.height) {
					Img.set({
						left: left,
						top: top,
						right: 0,
						bottom: 0,
						stroke: 0,
						padding: 0,
						// centeredScaling: true,
						hasControls: false,
						scaleX: scale,
						scaleY: scale
					});
				} else {
					Img.set({
						left: left,
						top: top,
						right: 0,
						bottom: 0,
						stroke: 0,
						padding: 0,
						// centeredScaling: true,
						hasControls: false,
						scaleX: scale,
						scaleY: scale
					});
				}
				//Img.scaleToWidth(width, false);
				fabricObj.add(Img);
				instance.addedObjects++;
			};
			image.src = imgBase64String;
		}

	} catch (err) {
		debugger
		console.log(err)
	}

}

PDFAnnotate.prototype.getAddedObjectsCount = function (blockUI, toaster) {
	var instance = this;
	var count = 0;
	$.each(instance.fabricObjects, function (index) {
		count += instance.fabricObjects[index].getObjects().length;
	});
	return new Promise(function (resolve) {
		resolve(count);
	});
}

PDFAnnotate.prototype.addBase64ImageToCanvas = function (imgBase64String, w = 100, showt, showp) {
	var inst = this;
	//var fabricObj = inst.fabricObjects[inst.active_canvas];
	if (inst.fabricObjects.length > 0) {
		$.each(inst.fabricObjects, function (index, fabricObj) {
			var image = new Image(w, "auto");
			image.onload = function () {
				fabricObj.add(new fabric.Image(image))
			}
			image.src = imgBase64String;
		});
	}
}

PDFAnnotate.prototype.deleteSelectedObject = function () {
	var inst = this;
	var activeObject = inst.fabricObjects[inst.active_canvas].getActiveObject();
	if (activeObject) {
		if (confirm('Are you sure to delete ?')) {
			inst.fabricObjects[inst.active_canvas].remove(activeObject);
			inst.addedObjects--;
		}
	}
}

PDFAnnotate.prototype.getAnnotatedPdf = function (blockUI, toaster) {
	var instance = this;
	var doc = new jspdf.jsPDF({ orientation: instance.orientation });
	instance.fabricObjects.forEach(function (fabricObj, index) {
		if (index != 0) {
			doc.addPage();
			doc.setPage(index + 1);
		}
		doc.addImage(
			fabricObj.toDataURL({
				format: 'png'
			}),
			instance.pageImageCompression == "NONE" ? "PNG" : "JPEG",
			0,
			0,
			doc.internal.pageSize.getWidth(),
			doc.internal.pageSize.getHeight(),
			`page-${index + 1}`,
			["FAST", "MEDIUM", "SLOW"].indexOf(instance.pageImageCompression) >= 0 ?
				instance.pageImageCompression :
				undefined
		);
	});
	return new Promise(function (resolve) {
		var BASE64MARKER = ';base64,';
		var dataURI = doc.output('datauristring');
		var base64Index = dataURI.indexOf(BASE64MARKER) + BASE64MARKER.length;
		var base64 = dataURI.substring(base64Index);
		resolve(base64);
	});
}


PDFAnnotate.prototype.savePdf = function (fileName) {
	var inst = this;
	var doc = new jspdf.jsPDF();
	if (typeof fileName === 'undefined') {
		fileName = `${new Date().getTime()}.pdf`;
	}

	inst.fabricObjects.forEach(function (fabricObj, index) {
		if (index != 0) {
			doc.addPage();
			doc.setPage(index + 1);
		}
		doc.addImage(
			fabricObj.toDataURL({
				format: 'png'
			}),
			inst.pageImageCompression == "NONE" ? "PNG" : "JPEG",
			0,
			0,
			doc.internal.pageSize.getWidth(),
			doc.internal.pageSize.getHeight(),
			`page-${index + 1}`,
			["FAST", "MEDIUM", "SLOW"].indexOf(inst.pageImageCompression) >= 0
				? inst.pageImageCompression
				: undefined
		);
		if (index === inst.fabricObjects.length - 1) {
			doc.save(fileName);
		}
	})
}

PDFAnnotate.prototype.setBrushSize = function (size) {
	var inst = this;
	$.each(inst.fabricObjects, function (index, fabricObj) {
		fabricObj.freeDrawingBrush.width = size;
	});
}

PDFAnnotate.prototype.setColor = function (color) {
	var inst = this;
	inst.color = color;
	$.each(inst.fabricObjects, function (index, fabricObj) {
		fabricObj.freeDrawingBrush.color = color;
	});
}

PDFAnnotate.prototype.setBorderColor = function (color) {
	var inst = this;
	inst.borderColor = color;
}

PDFAnnotate.prototype.setFontSize = function (size) {
	this.font_size = size;
}

PDFAnnotate.prototype.setBorderSize = function (size) {
	this.borderSize = size;
}

PDFAnnotate.prototype.clearActivePage = function () {
	var inst = this;
	var fabricObj = inst.fabricObjects[inst.active_canvas];
	var bg = fabricObj.backgroundImage;
	if (confirm('Are you sure?')) {
		fabricObj.clear();
		fabricObj.setBackgroundImage(bg, fabricObj.renderAll.bind(fabricObj));
	}
}

PDFAnnotate.prototype.serializePdf = function () {
	var inst = this;
	return JSON.stringify(inst.fabricObjects, null, 4);
}



PDFAnnotate.prototype.loadFromJSON = function (jsonData) {
	var inst = this;
	$.each(inst.fabricObjects, function (index, fabricObj) {
		if (jsonData.length > index) {
			fabricObj.loadFromJSON(jsonData[index], function () {
				inst.fabricObjectsData[index] = fabricObj.toJSON()
			})
		}
	})
}
